173	/**
174	 * Sync a single Hilo invoice to QuickBooks Online.
175	 *
176	 * Workflow:
177	 *   1. Fetch the invoice from our DB
178	 *   2. Fetch the flight school
179	 *   3. Find or create the QB customer
180	 *   4. Create a QB invoice with line items:
181	 *      - Line 1: Platform subscription (amount before tax)
182	 *      - Line 2: Sales tax (if applicable)
183	 *   5. Store the QB invoice ID back on our record
184	 *
185	 * @param invoiceId - Our internal invoice UUID
186	 * @param qbUserId - The user whose QB integration to use
187	 * @returns SyncResult with the QB invoice ID on success
188	 */
189	export async function syncInvoiceToQuickBooks(
190	  invoiceId: string,
191	  qbUserId: string,
192	): Promise<SyncResult> {
193	  try {
194	    // 1. Fetch invoice
195	    const [invoice] = await db
196	      .select()
197	      .from(invoices)
198	      .where(eq(invoices.id, invoiceId))
199	      .limit(1);
200	
201	    if (!invoice) {
202	      return { success: false, invoiceId, error: 'Invoice not found' };
203	    }
204	
205	    await qbConnectionRepo.findActive(invoice.flightSchoolId);
206	
207	    // Check if already synced
208	    const existingMeta = parseQBMeta(invoice.invoiceUrl);
209	    if (existingMeta?.qbInvoiceId) {
210	      return {
211	        success: true,
212	        invoiceId,
213	        qbInvoiceId: existingMeta.qbInvoiceId,
214	      };
215	    }
216	
217	    // 2. Fetch school
218	    const [school] = await db
219	      .select()
220	      .from(flightSchools)
221	      .where(eq(flightSchools.id, invoice.flightSchoolId))
222	      .limit(1);
223	
224	    if (!school) {
225	      return { success: false, invoiceId, error: 'Flight school not found' };
226	    }
227	
228	    // 3. Get QB client and find/create customer
229	    const client = await QuickBooksClient.create(qbUserId);
230	    const qbCustomerId = await findOrCreateQBCustomer(client, school);
231	
232	    // 4. Build QB invoice
233	    const periodMonth = invoice.periodStart
234	      ? new Date(invoice.periodStart).toLocaleString('en-US', {
235	          month: 'long',
236	          year: 'numeric',
237	        })
238	      : 'Current Period';
239	
240	    const poeCount = invoice.poeCount ?? 0;
241	    const subtotal = invoice.amount / 100; // Convert cents to dollars
242	    const taxAmount = (invoice.taxAmount ?? 0) / 100;
243	
244	    const lines: Array<{
245	      Amount: number;
246	      DetailType: string;
247	      Description?: string;
248	      SalesItemLineDetail?: {
249	        ItemRef?: { value: string; name?: string };
250	        UnitPrice?: number;
251	        Qty?: number;
252	      };
253	    }> = [
254	      {
255	        Amount: subtotal,
256	        DetailType: 'SalesItemLineDetail',
257	        Description: `Hilo ATOS Platform - ${periodMonth} - ${poeCount} POE`,
258	        SalesItemLineDetail: {
259	          ItemRef: { value: '1', name: 'Services' },
260	          UnitPrice: subtotal,
261	          Qty: 1,
262	        },
263	      },
264	    ];
265	
266	    if (taxAmount > 0) {
267	      lines.push({
268	        Amount: taxAmount,
269	        DetailType: 'SalesItemLineDetail',
270	        Description: 'Sales Tax',
271	        SalesItemLineDetail: {
272	          ItemRef: { value: '1', name: 'Services' },
273	          UnitPrice: taxAmount,
274	          Qty: 1,
275	        },
276	      });
277	    }
278	
279	    const dueDate = invoice.periodEnd
280	      ? new Date(invoice.periodEnd).toISOString().split('T')[0]
281	      : undefined;
282	
283	    const qbResult = await client.createInvoice({
284	      CustomerRef: { value: qbCustomerId },
285	      Line: lines,
286	      DueDate: dueDate,
287	      DocNumber: invoiceId.slice(0, 21), // QB limits DocNumber to 21 chars
288	      TxnDate: invoice.createdAt
289	        ? new Date(invoice.createdAt).toISOString().split('T')[0]
290	        : undefined,
291	      PrivateNote: `Hilo Invoice ID: ${invoiceId} | School: ${school.name} | Stripe: ${invoice.stripeInvoiceId ?? 'N/A'}`,
292	    });
293	
294	    const qbInvoiceId = qbResult.Invoice.Id;
295	
296	    // 5. Store QB metadata back on our invoice
297	    const meta: QBSyncMeta = {
298	      qbInvoiceId,
299	      qbCustomerId,
300	      syncedAt: new Date().toISOString(),
301	    };
302	
303	    await db
304	      .update(invoices)
305	      .set({ invoiceUrl: buildQBUrl(invoice.invoiceUrl, meta) })
306	      .where(eq(invoices.id, invoiceId));
307	
308	    lastSyncTime = new Date().toISOString();
309	    console.log(
310	      `[QB Sync] Invoice ${invoiceId} synced → QB Invoice ${qbInvoiceId}`,
311	    );
312	
313	    return { success: true, invoiceId, qbInvoiceId };
314	  } catch (err: unknown) {
315	    const msg =
316	      err instanceof Error ? err.message : 'Unknown error during invoice sync';
317	    console.error(`[QB Sync] Invoice sync failed for ${invoiceId}:`, msg);
318	    recordError(invoiceId, msg);
319	    return { success: false, invoiceId, error: msg };
320	  }
321	}
