323	/**
324	 * Sync a payment for an already-synced invoice to QuickBooks.
325	 *
326	 * Creates a QB Payment object that closes the AR for the QB invoice.
327	 * The invoice must be in 'paid' status and already synced to QB.
328	 *
329	 * @param invoiceId - Our internal invoice UUID
330	 * @param qbUserId - The user whose QB integration to use
331	 * @param paymentMethod - 'Credit Card' or 'ACH' (default: 'Credit Card')
332	 * @returns SyncResult with the QB payment ID on success
333	 */
334	export async function syncPaymentToQuickBooks(
335	  invoiceId: string,
336	  qbUserId: string,
337	  paymentMethod = 'Credit Card',
338	): Promise<SyncResult> {
339	  try {
340	    // 1. Fetch invoice (must be paid)
341	    const [invoice] = await db
342	      .select()
343	      .from(invoices)
344	      .where(eq(invoices.id, invoiceId))
345	      .limit(1);
346	
347	    if (!invoice) {
348	      return { success: false, invoiceId, error: 'Invoice not found' };
349	    }
350	
351	    await qbConnectionRepo.findActive(invoice.flightSchoolId);
352	
353	    if (invoice.status !== 'paid') {
354	      return {
355	        success: false,
356	        invoiceId,
357	        error: `Invoice status is "${invoice.status}", expected "paid"`,
358	      };
359	    }
360	
361	    // 2. Find the QB invoice reference
362	    const meta = parseQBMeta(invoice.invoiceUrl);
363	    if (!meta?.qbInvoiceId) {
364	      return {
365	        success: false,
366	        invoiceId,
367	        error: 'Invoice not yet synced to QuickBooks — sync the invoice first',
368	      };
369	    }
370	
371	    // Skip if payment already synced
372	    if (meta.qbPaymentId) {
373	      return {
374	        success: true,
375	        invoiceId,
376	        qbInvoiceId: meta.qbInvoiceId,
377	        qbPaymentId: meta.qbPaymentId,
378	      };
379	    }
380	
381	    // 3. Create QB payment
382	    const client = await QuickBooksClient.create(qbUserId);
383	    const totalAmount = (invoice.amount + (invoice.taxAmount ?? 0)) / 100;
384	
385	    const paymentResult = await client.markInvoicePaid({
386	      CustomerRef: { value: meta.qbCustomerId },
387	      TotalAmt: totalAmount,
388	      Line: [
389	        {
390	          Amount: totalAmount,
391	          LinkedTxn: [
392	            {
393	              TxnId: meta.qbInvoiceId,
394	              TxnType: 'Invoice',
395	            },
396	          ],
397	        },
398	      ],
399	      PaymentMethodRef: { value: '1', name: paymentMethod },

120	 * handle 401 responses by attempting a single token refresh + retry.
121	 */
122	export class QuickBooksClient {
123	  private accessToken: string;
124	  private refreshToken: string;
125	  private expiresAt: Date;
126	  private realmId: string;
127	  private userId: string;
128	  private integrationId: string;
129	
130	  private constructor(
131	    accessToken: string,
132	    refreshToken: string,
133	    expiresAt: Date,
134	    realmId: string,
135	    userId: string,
136	    integrationId: string,
137	  ) {
138	    this.accessToken = accessToken;
139	    this.refreshToken = refreshToken;
140	    this.expiresAt = expiresAt;
141	    this.realmId = realmId;
142	    this.userId = userId;
143	    this.integrationId = integrationId;
144	  }
145	
146	  /**
147	   * Create a new QuickBooks client for a given user.
148	   * Reads encrypted tokens from userIntegrations and decrypts them.
149	   *
150	   * @param userId - The user ID whose QB integration to load
151	   * @throws Error if no QuickBooks integration found for user
152	   */
153	  static async create(userId: string): Promise<QuickBooksClient> {
154	    const [row] = await db
155	      .select()
156	      .from(userIntegrations)
157	      .where(
158	        and(
159	          eq(userIntegrations.userId, userId),
160	          eq(userIntegrations.integrationType, 'quickbooks'),
161	        ),
162	      )
163	      .limit(1);
164	
165	    if (!row?.tokenData) {
166	      throw new Error('No QuickBooks integration found for user');
167	    }
168	
169	    const data = row.tokenData as QBTokenData;
170	
171	    return new QuickBooksClient(
172	      decrypt(data.accessToken),
173	      decrypt(data.refreshToken),
174	      new Date(data.expiresAt),
175	      data.realmId,
176	      userId,
177	      row.id,
178	    );
179	  }

